def linalg_solve_ex(A, B, *, left=True, check_errors=False):
    """
    Solve the linear system AX = B, returning (result, info).

    Args:
        A: (*, n, n) coefficient matrix
        B: (*, n, k) right-hand side matrix
        left: if True, solve AX = B
        check_errors: if True, raise error on singular matrix

    Returns:
        A named tuple (result, info) where:
        - result: (*, n, k) solution matrix
        - info: (*,) integer tensor, 0 = success, >0 = singular at that pivot
    """
    logger.debug("GEMS LINALG_SOLVE_EX")

    if not left:
        raise NotImplementedError("right=True (XA = B) is not yet supported")
    assert A.dtype in (
        torch.float32,
        torch.float64,
    ), f"linalg_solve_ex requires float32/float64, got {A.dtype}"
    if A.ndim < 2 or B.ndim < 2:
        raise ValueError("A and B must be at least 2D")
    if A.shape[-1] != A.shape[-2]:
        raise ValueError("A must be a square matrix")
    n = A.shape[-1]
    if B.shape[-2] != n:
        raise ValueError("B must have compatible dimensions with A")
    if A.numel() == 0 or B.numel() == 0:
        batch_shape = A.shape[:-2]
        info = torch.zeros(batch_shape, dtype=torch.int32, device=A.device)
        return B.clone(), info

    batch_shape = A.shape[:-2]
    batch = math.prod(batch_shape)
    nrhs = B.shape[-1]

    # No .clone() needed - kernel copies A->LU internally
    A_contig = A.reshape(batch, n, n).contiguous()
    B_contig = B.reshape(batch, n, nrhs).contiguous()
    LU = torch.empty_like(A_contig)
    X = torch.empty_like(B_contig)
    info = torch.empty(batch, dtype=torch.int32, device=A.device)

    block_n = triton.next_power_of_2(n) if n > 1 else 4
    block_k = triton.next_power_of_2(nrhs) if nrhs > 1 else 4

    linalg_solve_ex_kernel[(batch,)](
        A_contig,
        LU,
        B_contig,
        X,
        info,
        n,
        nrhs,
        A_contig.stride(0),
        A_contig.stride(1),
        LU.stride(0),
        LU.stride(1),
        B_contig.stride(0),
        B_contig.stride(1),
        X.stride(0),
        X.stride(1),
        BLOCK_N=block_n,
        BLOCK_K=block_k,
        num_warps=1,
        num_stages=1,
    )

    result = X.reshape(B.shape)
    info = info.reshape(batch_shape)

    if check_errors and torch.any(info != 0):
        raise torch.linalg.LinAlgError(
            "linalg.solve_ex: The diagonal element of the LU decomposition is zero."
        )

    return result, info
